const require_is = require("../utils/is.js");
const require_index = require("../useLatest/index.js");
let react = require("react");
//#region src/useUnmount/index.ts
function useUnmount(fn) {
	if (require_is.isDev) {
		if (!require_is.isFunction(fn)) console.error(`useUnmount expected parameter is a function, got ${typeof fn}`);
	}
	const fnRef = require_index.useLatest(fn);
	(0, react.useEffect)(() => () => {
		fnRef.current();
	}, [fnRef]);
}
//#endregion
exports.useUnmount = useUnmount;
